sourcesContent:
import { Fragment, useEffect, useState } from "react";
import "../css/home.css";
import { ConfigProvider, Panel, PanelHeader, Avatar, PanelHeaderContent, CardGrid, Card, PullToRefresh, FixedLayout, SimpleCell, Link, Div, Tabs, TabsItem, Footer, Placeholder, Button, Cell, List, Group } from "@vkontakte/vkui";
import bridge from "@vkontakte/vk-bridge";
import { Icon28WheelOutline, Icon28LogoVkColor, Icon28UserCircleOutline, Icon28MenuOutline, Icon28PollSquareOutline, Icon28GameOutline, Icon28LocationOutline, Icon28HeadphonesOutline, Icon28Gift, Icon28DiscussionsCircleFill, Icon28StoryQuestionCircleFillViolet, Icon28AddCircleFillBlue, Icon28GlobeOutline, Icon20StarsFilled, Icon56GestureOutline } from "@vkontakte/icons";
import { isDesktop, isMobile } from "react-device-detect";
const Home = (props) => {
	return (
		<ConfigProvider platform="android">
			<Panel id={props.id}>
				{props.screen === "home" && (
					<Fragment>
						<PanelHeader separator={false} before={<Avatar style={{ borderRadius: "50%" }} size={36} src={props.fetchedUser?.photo_200}/>}><PanelHeaderContent status={props.fetchedUser?.first_name + ' ' + props.fetchedUser?.last_name}>
			<span style={{ color: 'white' }}>Профиль</span>
		  </PanelHeaderContent>
						</PanelHeader>
						{props.loading === 0 && (
							<PullToRefresh onRefresh={props.refreshData} isFetching={props.isLoad}>
								<Fragment>
									<CardGrid
										style={{ padding: 20, paddingTop: 12, paddingBottom: 0 }} size="l">
										<Card className="BalanceImg">
											<div className="balance">
												<div className="coinsTop" style={{ color: "white" }}></div>
												<div className="coins">
													<div className="verticalText" style={{ lineHeight: "30px" }}>{number_format(props.userData.coins)}</div>
													<Icon28WheelOutline width={30} height={30}/>
												</div>
											</div>
										</Card>
										{props.userData.bonus.isActive && (
											<Card
												onClick={props.getBonus}
												className="BalanceImg button"
												style={{
													borderRadius: "var(--radius_button)",
													background: "var(--color_background_buttons)",
												}}
											>
												<div
													style={{
														display: "flex",
														justifyContent: "center",
														alignItems: "center",
														textAlign: "center",
														color: "#3c6",
														padding: 20,
														fontSize: 30,
														position: "relative",
														fontWeight: 500,
													}}
												><div
														style={{
															position: "absolute",
															transform: "rotate(40deg)",
															right: 0,
														}}
													></div>Получить бонус</div>
											</Card>
										)}
										<img
											onClick={props.openPromoModal}
											className="button"
											src={props.promoButtonImg}
											style={{
												display: "block",
												width: "100%",
												padding: 0,
												marginTop: 10,
												borderRadius: "var(--radius_button)",
											}}
										/>
										<Card className="BalanceImg">
											<div
												className="stat"
												style={{
													zIndex: 1,
												}}
											>
												<div
													style={{
														display: "flex",
														position: "relative",
														overflow: "hidden",
														borderRadius: "20px",
														height: 150,
													}}
												>
													<div
														style={{
															position: "absolute",
															top: 0,
															left: 0,
															right: 0,
															textAlign: "center",
															zIndex: 2,
														}}
													>
														<div
															style={{
																background: "white",
																padding: "5px 10px",
																borderRadius: "0 0 12px 12px",
																display: "inline-block",
																color: "#55585e",
															}}
														>
															Статистика за день
														</div>
													</div>
													<div
														style={{
															display: "flex",
															width: "50%",
															height: "100%",
															justifyContent: "center",
															alignItems: "center",
															color: "white",
															position: "relative",
														}}
													>
														<div
															style={{
																zIndex: 2,
																display: "flex",
																flexDirection: "column",
																justifyContent: "center",
																alignItems: "center",
															}}
														>
															<div
																style={{
																	fontWeight: "400",
																}}
															>
																Выигрыши
															</div>
															<div
																style={{
																	marginTop: 5,
																	fontWeight: "600",
																	fontSize: 21,
																}}
															>
																{props.userData.stats.day.win}
															</div>
														</div>
														<div
															style={{
																position: "absolute",
																left: 0,
																height: "100%",
																width: `${
																	!Number(
																		(
																			200 /
																			Number(
																				(
																					(props.userData.stats.day.lose +
																						props.userData.stats.day.win) /
																					props.userData.stats.day.win
																				).toFixed(2)
																			)
																		).toFixed(2)
																	)
																		? 100
																		: Number(
																				(
																					200 /
																					Number(
																						(
																							(props.userData.stats.day.lose +
																								props.userData.stats.day.win) /
																							props.userData.stats.day.win
																						).toFixed(2)
																					)
																				).toFixed(2)
																		  )
																}%`,
																background: "#3c6",
															}}
														></div>
													</div>
													<div
														style={{
															display: "flex",
															width: "50%",
															height: "100%",
															justifyContent: "center",
															alignItems: "center",
															color: "white",
															position: "relative",
														}}
													>
														<div
															style={{
																zIndex: 2,
																display: "flex",
																flexDirection: "column",
																justifyContent: "center",
																alignItems: "center",
															}}
														>
															<div
																style={{
																	fontWeight: "400",
																}}
															>
																Проигрыши
															</div>
															<div
																style={{
																	marginTop: 5,
																	fontWeight: "600",
																	fontSize: 21,
																}}
															>
																{props.userData.stats.day.lose}
															</div>
														</div>
														<div
															style={{
																position: "absolute",
																right: 0,
																height: "100%",
																background: "#d41132",
																width: `${
																	!Number(
																		(
																			200 /
																			Number(
																				(
																					(props.userData.stats.day.lose +
																						props.userData.stats.day.win) /
																					props.userData.stats.day.lose
																				).toFixed(2)
																			)
																		).toFixed(2)
																	)
																		? 100
																		: Number(
																				(
																					200 /
																					Number(
																						(
																							(props.userData.stats.day.lose +
																								props.userData.stats.day.win) /
																							props.userData.stats.day.lose
																						).toFixed(2)
																					)
																				).toFixed(2)
																		  )
																}%`,
															}}
														></div>
													</div>
												</div>
											</div>
										</Card>
										<Card className="BalanceImg">
											<div
												className="stat"
												style={{
													zIndex: 1,
												}}
											>
												<div
													style={{
														display: "flex",
														position: "relative",
														overflow: "hidden",
														borderRadius: "20px",
														height: 150,
													}}
												>
													<div
														style={{
															position: "absolute",
															top: 0,
															left: 0,
															right: 0,
															textAlign: "center",
															zIndex: 2,
														}}
													>
														<div
															style={{
																background: "white",
																padding: "5px 10px",
																borderRadius: "0 0 12px 12px",
																display: "inline-block",
																color: "#55585e",
															}}
														>
															За всё время
														</div>
													</div>
													<div
														style={{
															display: "flex",
															width: "50%",
															height: "100%",
															justifyContent: "center",
															alignItems: "center",
															color: "white",
															position: "relative",
														}}
													>
														<div
															style={{
																zIndex: 2,
																display: "flex",
																flexDirection: "column",
																justifyContent: "center",
																alignItems: "center",
															}}
														>
															<div
																style={{
																	fontWeight: "400",
																}}
															>
																Выигрыши
															</div>
															<div
																style={{
																	marginTop: 5,
																	fontWeight: "600",
																	fontSize: 21,
																}}
															>
																{props.userData.stats.all.win}
															</div>
														</div>
														<div
															style={{
																position: "absolute",
																left: 0,
																height: "100%",
																width: `${
																	!Number(
																		(
																			200 /
																			Number(
																				(
																					(props.userData.stats.all.lose +
																						props.userData.stats.all.win) /
																					props.userData.stats.all.win
																				).toFixed(2)
																			)
																		).toFixed(2)
																	)
																		? 100
																		: Number(
																				(
																					200 /
																					Number(
																						(
																							(props.userData.stats.all.lose +
																								props.userData.stats.all.win) /
																							props.userData.stats.all.win
																						).toFixed(2)
																					)
																				).toFixed(2)
																		  )
																}%`,
																background: "#3c6",
															}}
														></div>
													</div>
													<div
														style={{
															display: "flex",
															width: "50%",
															height: "100%",
															justifyContent: "center",
															alignItems: "center",
															color: "white",
															position: "relative",
														}}
													>
														<div
															style={{
																zIndex: 2,
																display: "flex",
																flexDirection: "column",
																justifyContent: "center",
																alignItems: "center",
															}}
														>
															<div
																style={{
																	fontWeight: "400",
																}}
															>
																Проигрыши
															</div>
															<div
																style={{
																	marginTop: 5,
																	fontWeight: "600",
																	fontSize: 21,
																}}
															>
																{props.userData.stats.all.lose}
															</div>
														</div>
														<div
															style={{
																position: "absolute",
																right: 0,
																height: "100%",
																background: "#d41132",
																width: `${
																	!Number(
																		(
																			200 /
																			Number(
																				(
																					(props.userData.stats.all.lose +
																						props.userData.stats.all.win) /
																					props.userData.stats.all.lose
																				).toFixed(2)
																			)
																		).toFixed(2)
																	)
																		? 100
																		: Number(
																				(
																					200 /
																					Number(
																						(
																							(props.userData.stats.all.lose +
																								props.userData.stats.all.win) /
																							props.userData.stats.all.lose
																						).toFixed(2)
																					)
																				).toFixed(2)
																		  )
																}%`,
															}}
														></div>
													</div>
												</div>
											</div>
										</Card>
									</CardGrid>
									<Footer
										style={{
											marginBottom: 60,
										}}
									>Онлайн: {props.userData.online}
									</Footer>
								</Fragment>
							</PullToRefresh>
						)}
					</Fragment>
				)}
				{props.screen === "rating" && (
					<Fragment>
						<PanelHeader
							separator={false}
							left={
								<Icon28PollSquareOutline
									width={36}
									height={36}
									style={{ borderRadius: "25%", marginLeft: 4 }}
								/>
							}
						>
							<PanelHeaderContent>
								<span style={{ color: "white" }}>Рейтинг</span>
							</PanelHeaderContent>
						</PanelHeader>
						<Tabs>
							{/* <TabsItem
							onClick={() => props.setActiveTabRating('topHour')}
							selected={props.activeTabRating === 'topHour'}
						>Топ часа</TabsItem> */}
							<TabsItem
								onClick={() => props.setActiveTabRating("topDay")}
								selected={props.activeTabRating === "topDay"}
							>
								Топ дня
							</TabsItem>
							<TabsItem
								onClick={() => props.setActiveTabRating("topWeek")}
								selected={props.activeTabRating === "topWeek"}
							>
								Топ недели
							</TabsItem>
						</Tabs>
						{props.activeTabRating === "topDay" && (
							<Fragment>
								{props.loading === 0 && (
									<Fragment>
										<CardGrid size="l">
											<Card className="BalanceImg">
												<div
													style={{
														background: `url(${props.ratingLabelImg}) 50% no-repeat`,
														backgroundSize: "cover",
														borderRadius: 12,
														marginTop: 10,
														// border: "1px solid GrayText",
														overflow: "hidden",
														padding: 15,
														paddingBottom: 0,
													}}
												>
													<div
														style={{
															display: "flex",
															color: "white",
															fontSize: 21,
															fontWeight: 600,
															alignItems: "center",
														}}
													>
														<Icon20StarsFilled width={28} height={28} />
														<div
															style={{
																marginLeft: 10,
																flexGrow: 1,
															}}
														>
															Топ дня
														</div>
													</div>
													<div
														style={{
															fontSize: 16,
															marginTop: 10,
														}}
													>
														Каждый день в 0:00 мы разыгрываем{" "}
														<span
															style={{
																fontWeight: 600,
															}}
														>
															{lil_format(props.topSumDay.reduce((acc, item) => acc + item, 0))} Coin
														</span>{" "}
														среди топ-{props.topSumDay.length} лучших игроков.
													</div>
													<br />
													<div
														style={{
															marginBottom: 20,
															display: "flex",
														}}
													>
														<div
															style={{
																width: "100%",
																textAlign: "center",
																color: "#f5f5f5",
															}}
														>
															<div
																style={{
																	opacity: 0.7,
																	fontSize: 11,
																	fontWeight: 400,
																}}
															>
																ВЫДАЧА ПРИЗОВ
															</div>
															<div
																style={{
																	fontSize: 18,
																	fontWeight: 600,
																	color: "#ffd54f",
																	whiteSpace: "nowrap",
																	padding: "0 10px",
																}}
															>
																в 0:00
															</div>
														</div>
														<div
															style={{
																width: 2,
																height: 30,
																background: "#f5f5f5",
																opacity: 0.5,
																marginTop: 5,
															}}
														></div>
														<div
															style={{
																width: "100%",
																textAlign: "center",
																color: "#f5f5f5",
															}}
														>
															<div
																style={{
																	opacity: 0.7,
																	fontSize: 11,
																	fontWeight: 400,
																}}
															>
																НАГРАДА
															</div>
															<div
																style={{
																	fontSize: 18,
																	fontWeight: 600,
																	color: "#ffd54f",
																	whiteSpace: "nowrap",
																	padding: "0 10px",
																}}
															>
																{lil_format(props.topSumDay.reduce((acc, item) => acc + item, 0))} Coin
															</div>
														</div>
													</div>
												</div>
											</Card>
										</CardGrid>
										<br />
